                  rows={10}
                  autoGrow={true}
                  className={!formState.content ? 'ion-invalid ion-touched' : ''}
                  errorText="Contenido es requerido"
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Hash de Contenido"
                  labelPlacement="floating"
                  value={formState.contentHash}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, contentHash: e.detail.value! }))}
