const toHermosillo = (utc: string | undefined | null): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  // Subtract 7 hours for UTC-7 (Hermosillo time)
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

const FactoryRunPage: React.FC = () => {
  const { userId, roleCode } = useUser();
  const [factoryRuns, setFactoryRuns] = useState<FactoryRun[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<string | undefined>(undefined);
  const [filterProjectSlug, setFilterProjectSlug] = useState<string | undefined>(undefined);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showFormModal, setShowFormModal] = useState(false);
  const [selectedFactoryRun, setSelectedFactoryRun] = useState<FactoryRun | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [formState, setFormState] = useState<Partial<CreateFactoryRunRequest>>({});
  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [page, setPage] = useState(0);
  const [isInfiniteDisabled, setInfiniteDisabled] = useState(false);
  const [expandedPrdSnapshot, setExpandedPrdSnapshot] = useState<number | null>(null);

  const ITEMS_PER_PAGE = 20;

  const [popoverState, setPopoverState] = useState({
    showAlertPopover: false,
    showMailPopover: false,
    event: undefined as Event | undefined,
  });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const loadFactoryRuns = async (pageNum: number, isInitialLoad: boolean = false, append: boolean = false) => {
    if (loading) return;
    setLoading(true);
    setError('');
    try {
      const allRuns = await getAllFactoryRuns({
        projectSlug: filterProjectSlug,
        organizationSlug: undefined, // Organization context not directly available from useUser for tenant_independent module, rely on existing data or projectSlug
        status: filterStatus,
      });

      const filteredBySearch = searchTerm
        ? allRuns.filter(run =>
            run.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
            run.prdModuleName.toLowerCase().includes(searchTerm.toLowerCase()) ||
            run.triggeredByEmail.toLowerCase().includes(searchTerm.toLowerCase())
          )
        : allRuns;

      const sortedRuns = filteredBySearch.sort((a, b) => new Date(b.created_At).getTime() - new Date(a.created_At).getTime());

      if (append) {
        setFactoryRuns(prev => {
          const newRuns = sortedRuns.slice(pageNum * ITEMS_PER_PAGE, (pageNum + 1) * ITEMS_PER_PAGE);
          setInfiniteDisabled(newRuns.length < ITEMS_PER_PAGE);
          return [...prev, ...newRuns];
        });
      } else {
        const initialRuns = sortedRuns.slice(0, ITEMS_PER_PAGE);
        setFactoryRuns(initialRuns);
        setInfiniteDisabled(initialRuns.length < ITEMS_PER_PAGE);
      }
    } catch (err) {
      setError((err as Error).message ?? 'Error loading factory runs');
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    setPage(0);
    setInfiniteDisabled(false);
    loadFactoryRuns(0, true);
  });

  useEffect(() => {
    setPage(0);
    setInfiniteDisabled(false);
    loadFactoryRuns(0, true);
  }, [searchTerm, filterStatus, filterProjectSlug]);

  const loadMoreItems = (ev: CustomEvent<void>) => {
    const nextPage = page + 1;
    loadFactoryRuns(nextPage, false, true);
    setPage(nextPage);
    (ev.target as HTMLIonInfiniteScrollElement).complete();
  };

  const handleCreateClick = () => {
    setIsEditing(false);
    setFormState({
      title: '',
      projectSlug: '',
      organizationSlug: '',
      prdModuleName: '',
      prdSnapshot: '',
      status: 'queued',
      triggeredByEmail: userId, // Assuming triggeredByEmail maps to current user's email
      reviewPassed: null,
      reviewScoreSummary: null,
      gitBranchName: null,
      errorSummary: null,
      active: true,
    });
    setSelectedFactoryRun(null);
    setShowFormModal(true);
  };

  const handleEditClick = async (id: number) => {
    setIsEditing(true);
    setLoading(true);
    setError('');
    try {
      const run = await getFactoryRunById(id);
      if (run) {
        setSelectedFactoryRun(run);
        setFormState({
          title: run.title,
          projectSlug: run.projectSlug,
          organizationSlug: run.organizationSlug,
          prdModuleName: run.prdModuleName,
          prdSnapshot: run.prdSnapshot,
          status: run.status,
          triggeredByEmail: run.triggeredByEmail,
          reviewPassed: run.reviewPassed,
          reviewScoreSummary: run.reviewScoreSummary,
          gitBranchName: run.gitBranchName,
          errorSummary: run.errorSummary,
          active: run.active,
        });
        setShowFormModal(true);
      } else {
        setError('Factory run not found.');
      }
    } catch (err) {
      setError((err as Error).message ?? 'Error fetching factory run details');
    } finally {
      setLoading(false);
    }
  };

  const handleViewDetailClick = async (id: number) => {
    setLoading(true);
    setError('');
    try {
      const run = await getFactoryRunById(id);
      if (run) {
        setSelectedFactoryRun(run);
        setShowDetailModal(true);
      } else {
        setError('Factory run not found.');
      }
    } catch (err) {
      setError((err as Error).message ?? 'Error fetching factory run details');
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    setError('');
    try {
      if (isEditing && selectedFactoryRun) {
        await updateFactoryRun(selectedFactoryRun.factoryRunId, formState);
      } else {
        await createFactoryRun(formState as CreateFactoryRunRequest);
      }
      setShowFormModal(false);
      setPage(0);
      setInfiniteDisabled(false);
      loadFactoryRuns(0, true);
    } catch (err) {
      setError((err as Error).message ?? 'Error saving factory run');
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteClick = (id: number) => {
    setSelectedFactoryRun(factoryRuns.find(run => run.factoryRunId === id) || null);
    setShowDeleteAlert(true);
  };

  const confirmDelete = async () => {
    if (selectedFactoryRun) {
      setLoading(true);
      setError('');
      try {
        await deleteFactoryRun(selectedFactoryRun.factoryRunId);
        setPage(0);
        setInfiniteDisabled(false);
        loadFactoryRuns(0, true);
      } catch (err) {
        setError((err as Error).message ?? 'Error deleting factory run');
      } finally {
        setLoading(false);
      }
    }
  };

  const getStatusColor = (status: FactoryRun['status']) => {
    switch (status) {
      case 'queued':
        return 'medium';
      case 'running':
        return 'warning';
      case 'succeeded':
        return 'success';
      case 'failed':
        return 'danger';
      case 'canceled':
        return 'light';
      default:
        return 'primary';
    }
  };

  const availableProjectSlugs = Array.from(new Set(factoryRuns.map(run => run.projectSlug)));

  return (
    <IonPage className="factory-run-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Ejecuciones de Fábrica — Factory GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />
      <IonContent fullscreen className="ion-padding">
        <IonLoading isOpen={loading} message={'Cargando...'} />
        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError('')}
          color="danger"
        />

        <div className="factory-run-filters">
          <IonSearchbar
            value={searchTerm}
            onIonInput={(e: CustomEvent<any>) => setSearchTerm(e.detail.value!)}
            placeholder="Buscar por título, módulo o email"
            debounce={300}
            fill="outline"
            label="Buscar"
            labelPlacement="floating"
          ></IonSearchbar>

          <IonSelect
            value={filterStatus}
            onIonChange={(e: CustomEvent<any>) => setFilterStatus(e.detail.value)}
            label="Filtrar por estado"
            labelPlacement="floating"
            fill="outline"
          >
            <IonSelectOption value={undefined}>Todos</IonSelectOption>
            <IonSelectOption value="queued">En cola</IonSelectOption>
            <IonSelectOption value="running">En ejecución</IonSelectOption>
            <IonSelectOption value="succeeded">Exitoso</IonSelectOption>
            <IonSelectOption value="failed">Fallido</IonSelectOption>
            <IonSelectOption value="canceled">Cancelado</IonSelectOption>
          </IonSelect>

          <IonSelect
            value={filterProjectSlug}
            onIonChange={(e: CustomEvent<any>) => setFilterProjectSlug(e.detail.value)}
            label="Filtrar por Proyecto"
            labelPlacement="floating"
            fill="outline"
          >
            <IonSelectOption value={undefined}>Todos</IonSelectOption>
            {availableProjectSlugs.map(slug => (
              <IonSelectOption key={slug} value={slug}>{slug}</IonSelectOption>
            ))}
          </IonSelect>
        </div>

        <IonList className="factory-run-list">
          {factoryRuns.map((run) => (
            <IonItem key={run.factoryRunId} detail={false} onClick={() => handleViewDetailClick(run.factoryRunId)} button>
              <div className="factory-run-item-content">
                <IonLabel>
                  <h2 className="factory-run-title">{run.title}</h2>
                  <p className="factory-run-metadata">
                    Proyecto: <strong>{run.projectSlug}</strong> | Org: <strong>{run.organizationSlug}</strong>
                  </p>
                  <p className="factory-run-email">Por: {run.triggeredByEmail}</p>
                  <p className="factory-run-date">Creado: {toHermosillo(run.created_At)}</p>
                </IonLabel>
                <div className="factory-run-item-actions">
                  <IonChip className="factory-run-chip">{run.prdModuleName}</IonChip>
                  <IonBadge color={getStatusColor(run.status)} className="factory-run-status-badge">{run.status}</IonBadge>
                  <IonButton fill="clear" color="primary" onClick={(e) => { e.stopPropagation(); handleEditClick(run.factoryRunId); }}>
                    <IonIcon icon={createOutline} slot="icon-only" />
                  </IonButton>
                  <IonButton fill="clear" color="danger" onClick={(e) => { e.stopPropagation(); handleDeleteClick(run.factoryRunId); }}>
                    <IonIcon icon={trashOutline} slot="icon-only" />
                  </IonButton>
                </div>
              </div>
            </IonItem>
          ))}
        </IonList>

        <IonInfiniteScroll
          onIonInfinite={(ev: CustomEvent<void>) => {
            loadMoreItems(ev);
          }}
          threshold="100px"
          disabled={isInfiniteDisabled}
        >
          <IonInfiniteScrollContent loadingText="Cargando más ejecuciones..."></IonInfiniteScrollContent>
