const BASE_URL = import.meta.env.VITE_API_URL ?? "https://smartloansbackend.azurewebsites.net";

export interface PricingPlan {
  pricingPlanId: number;
  planCode: string;
  planName: string;
  tagline?: string;
  priceMonthly: number;
  priceYearly?: number;
  currency: string;
  featuresList: string;
  ctaLabel: string;
  ctaUrl: string;
  isFeatured: boolean;
  isActive: boolean;
  sortOrder: number;
  created_At: string;
  updated_at?: string;
}

export interface PricingPlanListResponse {
  pricingPlans: PricingPlan[];
}

// GET ALL — POST /all_pricingPlans
export async function getAllPricingPlans(): Promise<PricingPlan[]> {
  const res = await fetch(BASE_URL + "/all_pricingPlans", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ pricingPlans: [{}] }), // No companyId, empty object as per backend_artifacts' docs for all_pricingPlans.txt
  });
  if (!res.ok) throw new Error(await res.text());
  const data: PricingPlanListResponse = await res.json();
  return data.pricingPlans ?? [];
}

// CREATE — action: 1
export async function createPricingPlan(payload: Omit<PricingPlan, "pricingPlanId" | "created_At" | "updated_at">): Promise<PricingPlan> {
  const res = await fetch(BASE_URL + "/pricingPlans", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ pricingPlans: [{ action: 1, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// UPDATE — action: 2
export async function updatePricingPlan(id: number, payload: Partial<Omit<PricingPlan, "created_At">_>): Promise<PricingPlan> {
  const res = await fetch(BASE_URL + "/pricingPlans", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ pricingPlans: [{ action: 2, pricingPlanId: id, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// DELETE — action: 3
export async function deletePricingPlan(id: number): Promise<void> {
  const res = await fetch(BASE_URL + "/pricingPlans", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ pricingPlans: [{ action: 3, pricingPlanId: id }] }),
  });
  if (!res.ok) throw new Error(await res.text());
}

import React, { useState, useEffect, useRef } from 'react';
import {
  IonContent, IonPage, IonList, IonItem, IonLabel, IonButton, IonIcon,
  IonLoading, IonToast, IonAlert, IonModal, IonInput, IonToggle,
  IonInfiniteScroll, IonInfiniteScrollContent, IonFab, IonFabButton,
  IonSpinner,
  useIonViewWillEnter,
} from '@ionic/react';
import {
  add, create, trash, informationCircle, checkmarkCircle, closeCircle, gridOutline
} from 'ionicons/icons';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useUser } from '../components/UserContext';
import {
  PricingPlan,
  getAllPricingPlans,
  createPricingPlan,
  updatePricingPlan,
  deletePricingPlan,
} from '../api/pricingPlanApi';
import './PricingPlanPage.css';

interface PlanFormState {
  planCode: string;
  planName: string;
  tagline: string;
  priceMonthly: number;
  priceYearly: number;
  currency: string;
  featuresList: string;
  ctaLabel: string;
  ctaUrl: string;
  isFeatured: boolean;
  isActive: boolean;
  sortOrder: number;
}

const PricingPlanPage: React.FC = () => {
  const { roleCode } = useUser();
  const isAdmin = roleCode === 'ADMIN'; // Assuming 'ADMIN' for admin role

  const [pricingPlans, setPricingPlans] = useState<PricingPlan[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState<PricingPlan | null>(null);
  const [planForm, setPlanForm] = useState<PlanFormState>({
    planCode: '',
    planName: '',
    tagline: '',
    priceMonthly: 0,
    priceYearly: 0,
    currency: 'MXN',
    featuresList: '',
    ctaLabel: '',
    ctaUrl: '',
    isFeatured: false,
    isActive: true,
    sortOrder: 0,
  });
  const [deleteAlert, setDeleteAlert] = useState<{ isOpen: boolean; id: number | null }>({ isOpen: false, id: null });
  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const infiniteScrollRef = useRef<HTMLIonInfiniteScrollElement | null>(null);
  const [isInfiniteDisabled, setInfiniteDisabled] = useState(false);
  const [page, setPage] = useState(1); // For infinite scroll, if the API supported pagination

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const toHermosillo = (utc: string | undefined): string => {
    if (!utc) return '';
    const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
    return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
  };

  const fetchPricingPlans = async () => {
    setLoading(true);
    setError('');
    try {
      const data = await getAllPricingPlans();
      setPricingPlans(data);
      // If API supported pagination, we'd check if more pages exist here to enable/disable infinite scroll
      setInfiniteDisabled(true); // Disable for now as backend doesn't support pagination
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar los planes de precios');
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    if (isAdmin) {
      fetchPricingPlans();
    }
  });

  useEffect(() => {
    if (isAdmin) {
      fetchPricingPlans();
    }
  }, [isAdmin]);

  const handleCreateClick = () => {
    setPlanForm({
      planCode: '',
      planName: '',
      tagline: '',
      priceMonthly: 0,
      priceYearly: 0,
      currency: 'MXN',
      featuresList: '',
      ctaLabel: '',
      ctaUrl: '',
      isFeatured: false,
      isActive: true,
      sortOrder: pricingPlans.length + 1, // Simple default for sortOrder
    });
    setShowCreateModal(true);
  };

  const handleEditClick = (plan: PricingPlan) => {
    setSelectedPlan(plan);
    setPlanForm({
      planCode: plan.planCode,
      planName: plan.planName,
      tagline: plan.tagline || '',
      priceMonthly: plan.priceMonthly,
      priceYearly: plan.priceYearly || 0,
      currency: plan.currency,
      featuresList: plan.featuresList,
      ctaLabel: plan.ctaLabel,
      ctaUrl: plan.ctaUrl,
      isFeatured: plan.isFeatured,
      isActive: plan.isActive,
      sortOrder: plan.sortOrder,
    });
    setShowEditModal(true);
  };

  const handleFormChange = (key: keyof PlanFormState, value: string | number | boolean) => {
    setPlanForm(prev => ({ ...prev, [key]: value }));
  };

  const handleSave = async () => {
    setSaving(true);
    setError('');
    try {
      if (selectedPlan) {
        await updatePricingPlan(selectedPlan.pricingPlanId, planForm);
      } else {
        await createPricingPlan(planForm);
      }
      fetchPricingPlans();
      setShowCreateModal(false);
      setShowEditModal(false);
      setSelectedPlan(null);
    } catch (err) {
      setError((err as Error).message ?? 'Error al guardar el plan de precios');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (deleteAlert.id === null) return;
    setLoading(true); // Use loading for delete since it's an action
    setError('');
    try {
      await deletePricingPlan(deleteAlert.id);
      fetchPricingPlans();
      setDeleteAlert({ isOpen: false, id: null });
    } catch (err) {
      setError((err as Error).message ?? 'Error al eliminar el plan de precios');
    } finally {
      setLoading(false);
    }
  };

  const loadMoreData = (ev: CustomEvent<void>) => {
    // In a real scenario, you'd increment page and fetch more data here.
    // For now, since backend does not support pagination, we just complete.
    (ev.target as HTMLIonInfiniteScrollElement).complete();
  };

  if (!isAdmin) {
    return (
      <IonPage>
        <Header
          presentAlertPopover={presentAlertPopover}
          presentMailPopover={presentMailPopover}
          screenTitle="Planes de Precios — Acceso Denegado"
        />
        <IonContent className="ion-padding">
          <p>No tienes permiso para ver esta página.</p>
        </IonContent>
      </IonPage>
    );
  }

  return (
    <IonPage className="pricing-plan-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Planes de Precios — POS GMO"
      />
      <IonContent fullscreen className="ion-padding">
        {loading && <IonLoading isOpen={loading} message="Cargando planes de precios..." duration={0} />}
        {error && <IonToast isOpen={!!error} message={error} onDidDismiss={() => setError('')} duration={3000} color="danger" />}

        <IonList className="pricing-plan-list">
          {pricingPlans.map(plan => (
            <IonItem key={plan.pricingPlanId} className="pricing-plan-item">
              <IonLabel>
                <h2>{plan.planName} ({plan.planCode})</h2>
                <p>{plan.tagline}</p>
                <p><strong>Precio Mensual:</strong> ${plan.priceMonthly.toFixed(2)} {plan.currency}</p>
                {plan.priceYearly && <p><strong>Precio Anual:</strong> ${plan.priceYearly.toFixed(2)} {plan.currency}</p>}
                <p><strong>Características:</strong> {plan.featuresList}</p>
                <p>
                  <strong>Destacado:</strong> {plan.isFeatured ? 'Sí' : 'No'}
                  {' | '}
                  <strong>Activo:</strong> {plan.isActive ? 'Sí' : 'No'}
                </p>
                <p><strong>Orden:</strong> {plan.sortOrder}</p>
                <p>Creado: {toHermosillo(plan.created_At)}</p>
                {plan.updated_at && <p>Actualizado: {toHermosillo(plan.updated_at)}</p>}
              </IonLabel>
              <IonButton fill="clear" onClick={() => handleEditClick(plan)}>
                <IonIcon icon={create} slot="icon-only" />
              </IonButton>
              <IonButton fill="clear" color="danger" onClick={() => setDeleteAlert({ isOpen: true, id: plan.pricingPlanId })}>
                <IonIcon icon={trash} slot="icon-only" />
              </IonButton>
            </IonItem>
          ))}
          <IonInfiniteScroll
            onIonInfinite={loadMoreData}
            threshold="100px"
            disabled={isInfiniteDisabled}
            ref={infiniteScrollRef}
          >
            <IonInfiniteScrollContent
              loadingSpinner="dots"
              loadingText="Cargando más planes de precios..."
            ></IonInfiniteScrollContent>
          </IonInfiniteScroll>
        </IonList>

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
          <IonFabButton onClick={handleCreateClick}>
            <IonIcon icon={add} />
          </IonFabButton>
        </IonFab>

        {/* Create/Edit Modal */}
        <IonModal
          isOpen={showCreateModal || showEditModal}
          onDidDismiss={() => {
            setShowCreateModal(false);
            setShowEditModal(false);
            setSelectedPlan(null);
            setError('');
          }}
        >
          <IonContent className="ion-padding pricing-plan-modal-content">
            <h2 className="ion-text-center">{selectedPlan ? 'Editar Plan de Precios' : 'Crear Nuevo Plan de Precios'}</h2>
            <div className="wizard-form-fields">
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Código de Plan *"
                  labelPlacement="floating"
                  value={planForm.planCode}
                  onIonInput={(e: CustomEvent<HTMLIonInputElement>) => handleFormChange('planCode', e.detail.value!)}
                  required
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre de Plan *"
                  labelPlacement="floating"
                  value={planForm.planName}
                  onIonInput={(e: CustomEvent<HTMLIonInputElement>) => handleFormChange('planName', e.detail.value!)}
                  required
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Descripción Corta"
                  labelPlacement="floating"
                  value={planForm.tagline}
                  onIonInput={(e: CustomEvent<HTMLIonInputElement>) => handleFormChange('tagline', e.detail.value!)}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Precio Mensual *"
                  labelPlacement="floating"
                  type="number"
                  value={planForm.priceMonthly}
                  onIonInput={(e: CustomEvent<HTMLIonInputElement>) => handleFormChange('priceMonthly', parseFloat(e.detail.value!))}
                  required
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Precio Anual"
                  labelPlacement="floating"
                  type="number"
                  value={planForm.priceYearly}
                  onIonInput={(e: CustomEvent<HTMLIonInputElement>) => handleFormChange('priceYearly', parseFloat(e.detail.value!))}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Moneda *"
                  labelPlacement="floating"
                  value={planForm.currency}
                  onIonInput={(e: CustomEvent<HTMLIonInputElement>) => handleFormChange('currency', e.detail.value!)}
                  required
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Lista de Características *"
                  labelPlacement="floating"
                  value={planForm.featuresList}
                  onIonInput={(e: CustomEvent<HTMLIonInputElement>) => handleFormChange('featuresList', e.detail.value!)}
                  required
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Etiqueta CTA *"
                  labelPlacement="floating"
                  value={planForm.ctaLabel}
                  onIonInput={(e: CustomEvent<HTMLIonInputElement>) => handleFormChange('ctaLabel', e.detail.value!)}
                  required
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="URL CTA *"
                  labelPlacement="floating"
                  type="url"
                  value={planForm.ctaUrl}
                  onIonInput={(e: CustomEvent<HTMLIonInputElement>) => handleFormChange('ctaUrl', e.detail.value!)}
                  required
                />
              </div>
              <IonItem lines="none">
                <IonLabel>¿Destacado?</IonLabel>
                <IonToggle
                  checked={planForm.isFeatured}
                  onIonChange={(e: CustomEvent<HTMLIonToggleElement>) => handleFormChange('isFeatured', e.detail.checked)}
                />
              </IonItem>
              <IonItem lines="none">
                <IonLabel>¿Activo?</IonLabel>
                <IonToggle
                  checked={planForm.isActive}
                  onIonChange={(e: CustomEvent<HTMLIonToggleElement>) => handleFormChange('isActive', e.detail.checked)}
                />
              </IonItem>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Orden de Clasificación *"
                  labelPlacement="floating"
                  type="number"
                  value={planForm.sortOrder}
                  onIonInput={(e: CustomEvent<HTMLIonInputElement>) => handleFormChange('sortOrder', parseInt(e.detail.value!, 10))}
                  required
                />
              </div>
            </div>
            <IonButton expand="block" onClick={handleSave} disabled={saving}>
              {saving ? <IonSpinner name="dots" /> : 'Guardar'}
            </IonButton>
            <IonButton expand="block" fill="outline" onClick={() => { setShowCreateModal(false); setShowEditModal(false); setSelectedPlan(null); setError(''); }}>
              Cancelar
            </IonButton>
            {error && <IonToast isOpen={!!error} message={error} onDidDismiss={() => setError('')} duration={3000} color="danger" />}
          </IonContent>
        </IonModal>

        <IonAlert
          isOpen={deleteAlert.isOpen}
          onDidDismiss={() => setDeleteAlert({ isOpen: false, id: null })}
          header="Confirmar Eliminación"
          message="¿Estás seguro de que quieres eliminar este plan de precios?"
          buttons=[
            {
              text: 'Cancelar',
              role: 'cancel',
              handler: () => setDeleteAlert({ isOpen: false, id: null }),
            },
            {
              text: 'Eliminar',
              handler: handleDelete,
            },
          ]
        />
      </IonContent>
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />
    </IonPage>
  );
};

export default PricingPlanPage;

